import{_ as t,o as a,c as i,a2 as n}from"./chunks/framework.Brv5O9VI.js";const u=JSON.parse('{"title":"Project Pitch & Interview Scripts","description":"","frontmatter":{},"headers":[],"relativePath":"00b-project-pitch.md","filePath":"00b-project-pitch.md"}'),o={name:"00b-project-pitch.md"};function r(s,e,c,l,d,h){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="project-pitch-interview-scripts" tabindex="-1">Project Pitch &amp; Interview Scripts <a class="header-anchor" href="#project-pitch-interview-scripts" aria-label="Permalink to &quot;Project Pitch &amp; Interview Scripts&quot;">​</a></h1><h2 id="_30-second-elevator-pitch" tabindex="-1">30-Second Elevator Pitch <a class="header-anchor" href="#_30-second-elevator-pitch" aria-label="Permalink to &quot;30-Second Elevator Pitch&quot;">​</a></h2><blockquote><p>&quot;I built the <strong>BIS &amp; AIS Regulatory Compliance Engine</strong>, an air-gapped compliance auditing platform that automates factory readiness evaluations and statutory standard identification for industrial and automotive products in India.</p><p>Instead of relying on slow, costly cloud LLMs, I engineered an ultra-fast local RAG pipeline using FastEmbed ONNX runtime embeddings, a FAISS vector index, and a Scikit-Learn classifier to resolve mandatory Quality Control Orders and AIS Homologation standards in under 20 milliseconds with zero external API calls.</p><p>The system features a 4-tier domain guardrail to prevent halluncinations or out-of-domain queries and computes statutory factory readiness percentages against official Scheme-I checklists, allowing compliance officers to export audit packs directly to CSV.&quot;</p></blockquote><hr><h2 id="_2-minute-comprehensive-technical-pitch" tabindex="-1">2-Minute Comprehensive Technical Pitch <a class="header-anchor" href="#_2-minute-comprehensive-technical-pitch" aria-label="Permalink to &quot;2-Minute Comprehensive Technical Pitch&quot;">​</a></h2><blockquote><p>&quot;Hello! The project I built is the <strong>BIS &amp; AIS Regulatory Compliance Engine</strong>. In India, manufacturers and importers face massive regulatory hurdles complying with mandatory Bureau of Indian Standards Quality Control Orders and Automotive Industry Standards homologation under CMVR Rule 126. Getting this wrong leads to factory shutdown notices, port confiscations, and heavy fines, while manually reviewing thousands of statutory gazettes takes weeks.</p><p>To solve this, I designed a full-stack, 100% air-gapped compliance audit engine. The system has two primary components: a high-performance Python FastAPI backend and a clean, responsive React 19 Single Page Application.</p><p>When a user queries a product—such as &#39;Ordinary Portland Cement 53 Grade&#39; or &#39;EV Traction Battery AIS 156&#39;—the backend processes the query through three distinct ML and search stages. First, a serialized Scikit-Learn model classifies the administrative ministry or department. Second, FastEmbed transforms the query into a 384-dimensional dense vector using the <code>BAAI/bge-small-en-v1.5</code> model running entirely locally on CPU via ONNX Runtime, requiring only 60 megabytes of memory and zero PyTorch dependencies. Third, a FAISS <code>IndexFlatIP</code> performs cosine nearest-neighbor search across our curated statutory corpus in less than 2 milliseconds.</p><p>To guarantee regulatory accuracy and prevent false positives, I implemented a 4-tiered domain guardrail in <code>guardrail.py</code>. It instantly passes exact statutory numbers with regular expressions, filters common commercial noise with keyword blacklists, verifies domain-specific terminology, and enforces a dense semantic threshold.</p><p>Once validated, our weighted gap engine in <code>gap_engine.py</code> dynamically evaluates the factory&#39;s verified artifacts—such as NABL calibration certificates, in-house test benches, and QC personnel undertakings—against the official BIS Scheme-I or AIS-037 checklist. It calculates an exact readiness percentage, flags critical non-compliances, and provides the statutory clause citations. Users can then export this complete determination as an RFC-4180 compliant CSV audit report.</p><p>In testing, the engine delivers sub-20ms inference latency, achieves 100% accuracy on our out-of-domain evaluation suite, and costs zero dollars per month in cloud AI API fees because it runs completely self-contained in a Docker container.&quot;</p></blockquote><hr><h2 id="behavioral-story-the-why-behind-the-architecture" tabindex="-1">Behavioral Story: The &#39;Why&#39; Behind the Architecture <a class="header-anchor" href="#behavioral-story-the-why-behind-the-architecture" aria-label="Permalink to &quot;Behavioral Story: The &#39;Why&#39; Behind the Architecture&quot;">​</a></h2><h3 id="why-air-gapped-local-ml-instead-of-openai-or-anthropic" tabindex="-1">Why Air-Gapped Local ML Instead of OpenAI or Anthropic? <a class="header-anchor" href="#why-air-gapped-local-ml-instead-of-openai-or-anthropic" aria-label="Permalink to &quot;Why Air-Gapped Local ML Instead of OpenAI or Anthropic?&quot;">​</a></h3><ol><li><strong>Confidentiality &amp; Statutory Privacy</strong>: Manufacturing companies entering new hardware or automotive prototypes will not submit proprietary formulations or bill of materials to third-party public cloud APIs.</li><li><strong>Deterministic Citations</strong>: Generic LLMs hallucinate non-existent Indian Standard numbers or cite outdated 1989 amendments. A vector index over vetted BIS gazettes guarantees 100% regulatory citation integrity.</li><li><strong>Zero Operating Expense</strong>: Operating an air-gapped FastEmbed ONNX model costs $0 in API tokens and functions in remote factory testing labs with zero internet connectivity.</li></ol>',10)])])}const m=t(o,[["render",r]]);export{u as __pageData,m as default};
